<?php require_once "../config/auth.php";requireAdmin();require_once "../config/database.php";$q=$conn->query("SELECT r.registration_id,r.user_id,r.event_id,u.name,u.register_no,u.department,e.event_name,e.event_date,a.status FROM event_registrations r JOIN users u ON r.user_id=u.id JOIN events e ON r.event_id=e.event_id LEFT JOIN attendance a ON a.user_id=u.id AND a.event_id=e.event_id ORDER BY r.registration_date DESC");if($_SERVER["REQUEST_METHOD"]==="POST"){$uid=(int)$_POST["user_id"];$eid=(int)$_POST["event_id"];$status=$_POST["status"];$s=$conn->prepare("INSERT INTO attendance(user_id,event_id,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),marked_at=CURRENT_TIMESTAMP");$s->bind_param("iis",$uid,$eid,$status);$s->execute();header("Location: registrations.php");exit;}?><!DOCTYPE html><html><head><title>Registrations</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><div class="logo">Admin</div><div class="nav-links"><a href="dashboard.php">Dashboard</a><a href="add-event.php">Add Event</a><a href="../logout.php">Logout</a></div></nav><div class="container"><h1>Event Registrations & Attendance</h1><div class="table-wrap"><table><tr><th>Student</th><th>Register No</th><th>Department</th><th>Event</th><th>Date</th><th>Attendance</th><th>Action</th></tr><?php while($r=$q->fetch_assoc()):?><tr><td><?=htmlspecialchars($r["name"])?></td><td><?=htmlspecialchars($r["register_no"])?></td><td><?=htmlspecialchars($r["department"])?></td><td><?=htmlspecialchars($r["event_name"])?></td><td><?=$r["event_date"]?></td><td><?=htmlspecialchars($r["status"]??"Not marked")?></td><td><form method="post" class="actions"><input type="hidden" name="user_id" value="<?=$r["user_id"]?>"><input type="hidden" name="event_id" value="<?=$r["event_id"]?>"><select name="status"><option>Present</option><option>Absent</option></select><button class="btn">Save</button></form></td></tr><?php endwhile;?></table></div></div></body></html>